            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj
    # Compute degrees
    degrees = [len(neighbors[i]) for i in range(n)]
    # Trivial cases
    if all(d == 0 for d in degrees):
        return [0] * n
    if all(d == n - 1 for d in degrees):
        return list(range(n))
    # Helper: check if coloring is valid
    def is_valid(col):
        for u in range(n):
            cu = col[u]
            for v in neighbors[u]:
                if cu == col[v]:
                    return False
        return True
    # Helper: greedy coloring with given order (first-fit)
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color
    # Helper: DSATUR coloring with optimized tie-breaking
    def dsatur():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = len(saturation[v])
                deg_v = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_v += 1
                if sat_v > best_sat or (sat_v == best_sat and deg_v > best_deg) or \
                   (sat_v == best_sat and deg_v == best_deg and random.random() < 0.5):
                    best_sat = sat_v
                    best_deg = deg_v
                    best_v = v
            v = best_v
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u].add(c)
        return color
    # Helper: RLF coloring with optimized selection
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            S = []
            best_v = -1
            best_deg = -1
            for v in uncolored:
                deg = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        deg += 1
                if deg > best_deg or (deg == best_deg and random.random() < 0.5):
                    best_deg = deg
                    best_v = v
            v = best_v
            S.append(v)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                adj_to_S = False
                for w in S:
                    if u in neighbors[w]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    U.remove(u)
                    W.add(u)
            while U:
                best_u = -1
                best_score = -1
                best_degU = n
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    degU = 0
                    for w in neighbors[u]:
                        if w in U:
                            degU += 1
                    if score > best_score or (score == best_score and degU < best_degU) or \
                       (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color
    # Helper: smallest-last ordering (Matula & Beck)
    def smallest_last_order():
        remaining = set(range(n))
        deg_copy = degrees[:]
        stack = []
        while remaining:
            min_v = -1
            min_deg = n
            for v in remaining:
                if deg_copy[v] < min_deg:
                    min_deg = deg_copy[v]
                    min_v = v
            stack.append(min_v)
            remaining.remove(min_v)
            for u in neighbors[min_v]:
                if u in remaining:
                    deg_copy[u] -= 1
        return list(reversed(stack))
    # Helper: adaptive saturation weighting (novel heuristic)
    def adaptive_saturation_weighted():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        # Adaptive weights: increase weight for colors that cause high future saturation
        color_weights = [1.0] * n  # dynamic weight per color
        uncolored_count = n
        while uncolored:
            best_v = -1
            best_score = -1
            for v in uncolored:
                sat_v = len(saturation[v])
                deg_v = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_v += 1
                # Adaptive score: saturation degree + weighted degree penalty
                score = sat_v + 0.1 * sum(color_weights[c] for c in saturation[v]) + 0.01 * deg_v
                if score > best_score or (score == best_score and random.random() < 0.5):
                    best_score = score
                    best_v = v
            v = best_v
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation and adaptive weights
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u].add(c)
                    # Increase weight for color c if it appears in many saturated neighbors
                    color_weights[c] += 0.5 / max(1, len(saturation[u]))
        return color
    # Helper: maximal independent set extraction via greedy degree ordering
    def maximal_independent_set_coloring():
        color = [-1] * n
        uncolored = set(range(n))
        color_class = 0
        while uncolored:
            # Build maximal independent set using degree ordering in subgraph
            degrees_sub = [0] * n
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        degrees_sub[v] += 1
            # Order by degree descending in subgraph
            order = sorted(uncolored, key=lambda x: degrees_sub[x], reverse=True)
            S = []
            blocked = set()
            for v in order:
                if v in uncolored and v not in blocked:
                    S.append(v)
                    blocked.add(v)
                    for u in neighbors[v]:
                        if u in uncolored:
                            blocked.add(u)
            # Assign color to independent set S
            for v in S:
                color[v] = color_class
                uncolored.remove(v)
            color_class += 1
        return color
    # Try multiple orderings and heuristics
    best_coloring = None
    best_colors = float('inf')
    orderings = [
        list(range(n)),  # natural
        sorted(range(n), key=lambda x: degrees[x], reverse=True),  # degree descending
        smallest_last_order()  # smallest-last
    ]
    for order in orderings:
        # greedy
        col_greedy = greedy_color(order)
        if is_valid(col_greedy):
            colors_used = max(col_greedy) + 1 if col_greedy else 0
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = col_greedy[:]
        # DSATUR
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            colors_used = max(col_dsatur) + 1 if col_dsatur else 0
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = col_dsatur[:]
        # RLF
        col_rlf = rlf()
        if is_valid(col_rlf):
            colors_used = max(col_rlf) + 1 if col_rlf else 0
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = col_rlf[:]
        # Adaptive saturation weighted
        col_adap = adaptive_saturation_weighted()
        if is_valid(col_adap):
            colors_used = max(col_adap) + 1 if col_adap else 0
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = col_adap[:]
        # Maximal independent set
        col_mis = maximal_independent_set_coloring()
        if is_valid(col_mis):
            colors_used = max(col_mis) + 1 if col_mis else 0
            if colors_used < best_colors:
                best_colors = colors_used
                best_coloring = col_mis[:]
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
    # Local search improvement: Kempe chain to reduce colors with early termination
    def kempe_reduce(col):
        current = col[:]
        k = max(current) + 1 if current else 0
        # Limit iterations to avoid timeout
        max_iters = 15
        iters = 0
        improved = True
        while improved and k > 1 and iters < max_iters:
            iters += 1
            improved = False
            target = k - 1
            verts = [v for v in range(n) if current[v] == target]
            if not verts:
                k -= 1
                improved = True
                continue
            for v in verts:
                for c in range(target):
                    conflict = False
                    for u in neighbors[v]:
                        if current[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                for v in verts:
                    for c in range(target):
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in neighbors[x]:
                                if not visited[y] and (current[y] == target or current[y] == c):
                                    visited[y] = True
                                    queue.append(y)
                        has_conflict = False
                        for u in neighbors[v]:
                            if current[u] == c:
                                if not visited[u]:
                                    has_conflict = True
                                    break
                            elif current[u] == target:
                                if visited[u]:
                                    has_conflict = True
                                    break
                        if not has_conflict:
                            for x in component:
                                if current[x] == target:
                                    current[x] = c
                                else:
                                    current[x] = target
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if not improved:
                break
            k = max(current) + 1
        return current
    best_coloring = kempe_reduce(best_coloring)
    if not is_valid(best_coloring):
        best_coloring = greedy_color(list(range(n)))
    return best_coloring
